        num_i = b[1]*a[0] - b[0]*a[1]
        den = a[0]**2 + a[1]**2
        if num_r % den == 0 and num_i % den == 0:
            return True
        return False

    # Build adjacency for divisibility (excluding self)
    adj = {i: set() for i in range(len(elements))}
    for i in range(len(elements)):
        for j in range(len(elements)):
            if i != j and divides(elements[i], elements[j]):
                adj[i].add(j)

    # Find max antichain using brute force (since n is small, len(elements) <= 20 for n=4)
    import itertools
    best = 0
    for r in range(len(elements), 0, -1):
