{"operation":"run_python","code":"def max_path(n):
    # Grid is 0..n-1, 0..n-1
    # Start at (0,0)
    # Move types: D (diagonal), H (horizontal/axis-aligned)
    # Alternating D, H, D, H...
    # D moves: (dx, dy) in {(1,1), (1,-1), (-1,1), (-1,-1)}
    # H moves: (dx, dy) in {(1,0), (-1,0), (0,1), (0,-1)}

    best = 0
    def dfs(x, y, move_type, visited_count):
        nonlocal best
        if visited_count > best:
            best = visited_count

        if move_type == 'D':
            for dx, dy in [(1,1), (1,-1), (-1,1), (-1,-1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    dfs(nx, ny, 'H', visited_count + 1)
                    visited.remove((nx, ny))
        else: # H
            for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    dfs(nx, ny, 'D', visited_count + 1)
                    visited.remove((nx, ny))

    visited = {(0,0)}
    dfs(0, 0, 'D', 1)
    return best

